def resolve_industry_funnel(val: Any) -> Tuple[str, str]:
    """
    Resolves any Gemini Industry Funnel prediction (number string, integer,
    funnel name, or Tracxn Hex ID) into (funnel_name, funnel_id).
    
    Returns:
        (funnel_name, funnel_id) if resolved, or ('', '') if unresolved.
    """
    if val is None:
        return ('', '')
    
    s = str(val).strip()
    if not s:
        return ('', '')
    
    # 1. Direct match by Base Prompt Number ('1'..'21')
    if s in NUMBER_TO_FUNNEL:
        return (NUMBER_TO_FUNNEL[s]['name'], NUMBER_TO_FUNNEL[s]['id'])
    
    # Check if number with period e.g. '1.', '1. Business Services'
    m = re.match(r'^(\d{1,2})([.:\s]|$)', s)
    if m:
        num_prefix = m.group(1)
        if num_prefix in NUMBER_TO_FUNNEL:
            return (NUMBER_TO_FUNNEL[num_prefix]['name'], NUMBER_TO_FUNNEL[num_prefix]['id'])
    
    # 2. Direct match by Tracxn Hex ID (24-char hex)
    if s in ID_TO_FUNNEL:
        return (ID_TO_FUNNEL[s]['name'], ID_TO_FUNNEL[s]['id'])
    
    # 3. Match by Funnel Name (exact case-insensitive)
    s_low = s.lower()
    if s_low in NAME_TO_FUNNEL:
        return (NAME_TO_FUNNEL[s_low]['name'], NAME_TO_FUNNEL[s_low]['id'])
    
    # 4. Partial / prefix match on name (e.g. 'Logistics Transportation')
    if len(s_low) >= 6:
        for norm_name, entry in NAME_TO_FUNNEL.items():
            if norm_name.startswith(s_low) or s_low.startswith(norm_name):
                return (entry['name'], entry['id'])
    
    return ('', '')


def build_default_funnel_maps() -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    """
    Builds the exact (funnel_name_map, funnel_id_map, funnel_num_map) structure
    expected by main.py, fully pre-populated with all 1,361 funnels.
    """
    funnel_name_map: Dict[str, Any] = {'name': [], 'id': []}
    funnel_id_map: Dict[str, Any] = {'name': [], 'id': []}
    funnel_num_map: Dict[str, Any] = {'name': [], 'id': []}

    for r in ALL_FUNNEL_ROWS:
        name = r[0] if len(r) > 0 else ''
        fid = r[1] if len(r) > 1 else ''
        pnum = r[8] if len(r) > 8 else ''

        if name and name not in funnel_name_map:
            funnel_name_map[name] = r
            funnel_name_map['name'].append(name)
            funnel_name_map['id'].append(fid)
        if fid and fid not in funnel_id_map:
            funnel_id_map[fid] = r
            funnel_id_map['name'].append(name)
            funnel_id_map['id'].append(fid)
        if pnum and pnum not in funnel_num_map:
            funnel_num_map[pnum] = r
            funnel_num_map['name'].append(name)
            funnel_num_map['id'].append(fid)

    return (funnel_name_map, funnel_id_map, funnel_num_map)
